    ". نمرات زیر، ثبت‌های همین بازه‌اند و نمره نهایی درس نیستند.</p>";
  if (!m.sessions.length)
    h +=
      '<div class="empty">در این بازه و محدوده، جلسه مرتبطی ثبت نشده است.</div>';
